import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { Box, Button, Checkbox, Container, FormControlLabel, TextField, Typography } from '@mui/material';
import schema from '../validations/formAppSchema';

export default function FormApp() {
  const [sent, setSent] = useState(false);

  const {register, handleSubmit, formState: {errors, isSubmitting}, reset} = useForm({
    defaultValues: {
      name: '',
      email: '',
      title: '',
      message: '',
      agreement: false,
    },
    resolver: yupResolver(schema),
  });

  const onSubmit = async (data) => {
    // ここでAPI送信などを実装（いまは疑似送信）
    await new Promise((r) => setTimeout(r, 600));
    setSent(true);
    reset({ name: '', email: '', title: '', message: '', agreement: false });
  };

  return (
    <Container component="form" maxWidth="sm" onSubmit={handleSubmit(onSubmit)} noValidate sx={{my: 2}}>{/* formタグを使用しない */}
      {sent &&
      <Box role="status" aria-live="polite">{/* role="status"はWAI-ARIAの属性の1つで、ウェブページ上の状態や進捗状況をスクリーンリーダーに伝えるために使用、
      これによりユーザーはWebサイトやアプリケーションの状態の変化を音声や点字で知ることができる、
      aria-live="polite"を設定した要素が更新された場合、スクリーンリーダーはユーザーが他の操作をしていないタイミングでその変更を読み上げる、
      これによりユーザーの操作を妨げることなく重要な情報を伝えることができる */}
        <Typography sx={{color: 'success.main'}}>お問い合わせありがとうございます。内容を確認後、担当者よりご連絡いたします。</Typography>
      </Box>}

      <TextField
      id="name"
        label="お名前"
        autoComplete="name"//autoComplete属性を付けることでブラウザがフィールドの役割を明確に認識し正しい候補を提案できる
        placeholder="山田 太郎"
        fullWidth
        margin="none"
        error={!!errors.name}//MUIのTextFieldのerrorプロパティはtrueのときだけ赤枠＆エラースタイルを適用する仕様、
        //errors.nameが存在するかどうかを真偽値に変換して渡す必要有
        helperText={errors.name?.message}
                slotProps={{//slotPropsは内部パーツだけをピンポイントでカスタマイズできる、余計なCSSの上書きやテーマ変更をせずに局所的に調整できる
    formHelperText: {sx: {fontSize: 14}}
  }}

        sx={{my: 2}}
        {...register('name')}//左記によりname="name"が自動で設定される、値変更時やフォーカスアウト時にReact Hook Formが処理できる、
        //DOM参照がセットされる＝この1行でフォーム要素をReact Hook Formの管理下に置くというセットアップが完了する
        />

      <TextField
      id="email"
        label="メールアドレス"
                autoComplete="email"

        placeholder="taro@example.com"
        type="email"
        fullWidth
        margin="none"
        error={!!errors.email}
        helperText={errors.email?.message}
        slotProps={{
    formHelperText: {sx: {fontSize: 14}}
  }}
                sx={{my: 2}}

        {...register('email')}
      />

      <TextField
      id="title"
        label="件名"
        autoComplete="off"
        placeholder="お問い合わせの件名"
        fullWidth
        margin="none"
        error={!!errors.title}
        helperText={errors.title?.message}
                slotProps={{
    formHelperText: {sx: {fontSize: 14}}
  }}

                sx={{my: 2}}

        {...register('title')}
      />

      <TextField
      id="message"
        label="本文"
        autoComplete="off"
        placeholder="お問い合わせ内容をご記入ください"
        fullWidth
        margin="none"
        multiline
        rows={5}
        error={!!errors.message}
        helperText={errors.message?.message}
                slotProps={{
    formHelperText: {sx: {fontSize: 14}}
  }}

                sx={{my: 2}}

        {...register('message')}

      />

      <FormControlLabel
        control={<Checkbox {...register('agreement')} sx={{py: 0}} />}
        label="プライバシーポリシーに同意する"

        sx={{display: 'block', mt: 2, mb: errors.agreement ? 0 : 2}}//エラーがあるときはmbなしにして見た目の調節
      />
      {errors.agreement && (
        <Box sx={{color: 'error.main', fontSize: 14, ml: 2}}>{errors.agreement.message}</Box>
      )}

      <Button type="submit" variant="contained" sx={{my: 2}} disabled={isSubmitting}>{/* disabled={isSubmitting}によりisSubmittingがtrueのときはボタンが無効化、
      送信中(onSubmit内のPromiseが解決するまでは true になります。
	•	送信中に連打されないようにするための防止策。
*/}
        {isSubmitting ? '送信中…' : '送信'}
      </Button>
    </Container>
  );
}
